  isVertical: boolean,
  isEven: boolean,
  alternating: boolean,
  alignment: "top/left" | "bottom/right"
): string {
  return isVertical
    ? alternating
      ? isEven
        ? "h-px w-4 left-0"
        : "h-px w-4 right-0"
      : alignment === "top/left"
        ? "h-px w-4 left-0"
        : "h-px w-4 right-0"
    : alternating
